// npm run seed        -> bank accounts + one sample lottery
// npm run seed:demo   -> same + fake sold tickets so the page looks like your screenshots
import crypto from 'node:crypto';
import mongoose from 'mongoose';
import { connectDB } from './db.js';
import * as M from './models/index.js';

const demo = process.argv.includes('--demo');
await connectDB();
for (const m of Object.values(M)) await m.createIndexes();

if (!(await M.BankAccount.countDocuments())) {
  await M.BankAccount.insertMany(
    [
      ['Tele Birr', '0999972486'],
      ['Commercial Bank of Ethiopia', '1000804500573'],
      ['BOA', '269980524'],
      ['Awash Bank', '000000000000'], // <- change in the admin panel
    ].map(([bankName, accountNumber], i) => ({
      bankName,
      accountNumber,
      accountName: 'Getachew Fikadu Jirata',
      sortOrder: i,
    }))
  );
  console.log('Bank accounts added (edit them in the admin panel).');
}

let lottery = await M.Lottery.findOne({ title: '6 Gech EV Makina Equb' });
if (!lottery) {
  lottery = await M.Lottery.create({
    title: '6 Gech EV Makina Equb',
    carName: 'BYD Leo Pard 7',
    carColor: 'Black',
    imageUrl: '/uploads/placeholder-car.svg',
    ticketPrice: 6000,
    totalTickets: 4000,
    endsAt: new Date(Date.now() + (2 * 86400 + 9 * 3600 + 59 * 60) * 1000),
    featured: true,
  });
  console.log('Sample lottery created.');
}

if (demo && !(await M.Ticket.countDocuments({ lottery: lottery._id }))) {
  const demoUser = await M.User.findOneAndUpdate(
    { telegramId: 1 },
    { telegramId: 1, firstName: 'Demo', language: 'en', phone: '+251911000000' },
    { upsert: true, returnDocument: "after" }
  );
  const order = await M.Order.create({
    code: 'DEMO000001',
    user: 1,
    lottery: lottery._id,
    fullName: 'Demo Buyer',
    phone: demoUser.phone,
    receiptUrl: '/uploads/placeholder-car.svg',
    total: 3070 * lottery.ticketPrice,
    status: 'APPROVED',
  });
  const nums = Array.from({ length: lottery.totalTickets }, (_, i) => i + 1);
  for (let i = nums.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  await M.Ticket.insertMany(
    nums.slice(0, 3070).map((number) => ({
      lottery: lottery._id,
      number,
      order: order._id,
      user: 1,
      status: 'TAKEN',
    }))
  );
  console.log('Demo: 3,070 tickets marked as sold.');
}

await mongoose.disconnect();
console.log('Seed finished.');
